class Solution {
public:
    int maxSubstringLength(string s) {
        vector<int> first(26, -1), last(26, -1);
        int n = s.size();
        for (int i = 0; i < n; ++i) {
            int c = s[i] - 'a';
            if (first[c] == -1) first[c] = i;
            last[c] = i;
        }

        int ans = -1;
        for (int ch = 0; ch < 26; ++ch) {
            if (first[ch] == -1) continue;
            int i = first[ch];
            int max_last = last[ch];
            for (int j = i; j < n; ++j) {
                int c = s[j] - 'a';
                if (first[c] < i) break;
                if (last[c] > max_last) max_last = last[c];
                if (j == max_last) {
                    if (!(i == 0 && j == n - 1)) {
                        ans = max(ans, j - i + 1);
                    }
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int maxSubstringLength(String s) {
        int[] first = new int[26];
        int[] last = new int[26];
        Arrays.fill(first, -1);
        Arrays.fill(last, -1);
        int n = s.length();

        for (int i = 0; i < n; i++) {
            int c = s.charAt(i) - 'a';
            if (first[c] == -1) first[c] = i;
            last[c] = i;
        }

        int ans = -1;
        for (int ch = 0; ch < 26; ch++) {
            if (first[ch] == -1) continue;
            int i = first[ch];
            int maxLast = last[ch];
            for (int j = i; j < n; j++) {
                int c = s.charAt(j) - 'a';
                if (first[c] < i) break;
                if (last[c] > maxLast) maxLast = last[c];
                if (j == maxLast) {
                    if (!(i == 0 && j == n - 1)) {
                        ans = Math.max(ans, j - i + 1);
                    }
                }
            }
        }
        return ans;
    }
}

var maxSubstringLength = function(s) {
    const first = new Array(26).fill(-1);
    const last = new Array(26).fill(-1);
    const n = s.length;

    for (let i = 0; i < n; i++) {
        const c = s.charCodeAt(i) - 97;
        if (first[c] === -1) first[c] = i;
        last[c] = i;
    }

    let ans = -1;
    for (let ch = 0; ch < 26; ch++) {
        if (first[ch] === -1) continue;
        const i = first[ch];
        let maxLast = last[ch];
        for (let j = i; j < n; j++) {
            const c = s.charCodeAt(j) - 97;
            if (first[c] < i) break;
            if (last[c] > maxLast) maxLast = last[c];
            if (j === maxLast) {
                if (!(i === 0 && j === n - 1)) {
                    ans = Math.max(ans, j - i + 1);
                }
            }
        }
    }
    return ans;
};
